import{z as s,x as i,o as B,c as d,q as t,j as r,D as e,d as n,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"交易卡数据","description":"","frontmatter":{"title":"交易卡数据","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-card-data.md","filePath":"quant/alt-card-data.md","lastUpdated":1791063341000}'),p={name:"quant/alt-card-data.md"};function C(m,E,h,u,D,F){const A=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="交易卡数据" tabindex="-1">交易卡数据 <a class="header-anchor" href="#交易卡数据" aria-label="Permalink to &quot;交易卡数据&quot;">​</a></h1><div class="epigraph"><p>卡数据的诚实从两个时钟开始：授权告诉你买了，结算告诉你钱动了；把两者混成一个日期，日历就会替你造出并不存在的 alpha。</p><footer>—— 据 Ganong and Noel, American Economic Review, 2019；Baker, Farrokhnia, Meyer, Pagel and Yannelis, Review of Financial Studies, 2020 整理</footer></div><p><a href="/quant/alt-geo-deep">上一课</a>把空间传感器对齐到公司与面板，误差收敛到映射与加总规则。本课处理另一种个体级面板：卡与账户流水。主干课的<a href="/quant/card-spending">交易卡数据</a>立了口径：Gross–Souleles 与 Ganong–Noel 说明流水能识别流动性约束下的消费；这是家庭金融与近实时宏观，不是默认的股票 alpha；商户映射、授权与结算、样本代表性都被点名。本课做工程深化：把这些坑变成可测的机制——双时钟、商户图谱、代表性校准与发行人残差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口在「坑被点名」与「坑被测量」之间。授权与结算是两个时钟：授权先发生，结算可能改金额、拆单或撤销，退款数周后负向回流；只按一个日期记账，政策支票到账周的「消费激增」里混着永远不结算的授权。商户是图谱不是字段：商户类别码与品牌实体不一致，一个零售集团几十个收单主体，映射不修订，同一家公司的销售额被拆到多家证券。面板在漂移：用户进出、发卡机构构成变化、激励活动改变刷卡行为，总量漂移与真实需求同形。聚合合规：数据只能在聚合层以上使用，个人级明细不可留存。这四件事不做成机制，nowcast 的误差无从归因。</p><p><span class="marginnote">nowcast 可译作「即时预测」：用高频数据估计还没公布的本期总量——比如用 4 月的刷卡流水猜 4 月官方零售额，而官方数字 5 月中才发布。它猜的是「现在」而不是未来，所以对数据交付延迟极其敏感，延迟账算错，信号就变成事后诸葛亮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>其一，双时间戳表：每笔记录带授权时刻与结算时刻，金额两版，退款是负行而不是字段修正；任何日度聚合都声明用哪个时钟。其二，商户解析表：收单名到品牌实体再到证券的映射，带版本与可得日期，映射修订走生效日而不是回写——与<a href="/quant/corporate-action-engine">公司行动</a>同一纪律。其三，代表性校准：把面板聚合消费对照发卡行财报与官方零售序列，报告比率及其漂移；比率不平稳的时段，nowcast 只做方向不做水平。其四，发行人残差：行业中性、季节调整后取公司残差，主干课的判据在这里变成每日作业；Ganong–Noel 的失业后支出骤降之所以可信，靠的是个体内对齐，不是总量对比。其五，交付延迟账：周频面板的延迟分布决定 nowcast 的可用日，信号时钟跟交付走。</p><p><span class="marginnote">行业中性就像赛跑只看选手比同组平均快多少：先把公司销售额减去所在行业的整体涨跌，剩下的才是这家公司自己的故事。不做这一步，行业普涨会把所有成员一起抬高，你以为买到了公司 alpha，实际拿到的是行业 beta。</span></p>',9)),(B(),r(o,null,{default:e(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8E%88%E6%9D%83%E6%B5%81%EF%BC%9Aauth%20%E6%97%B6%E5%88%BB%22%5D%20--%3E%20R%5B%22%E5%8F%8C%E6%97%B6%E9%97%B4%E6%88%B3%E8%AE%B0%E5%BD%95%E8%A1%A8%22%5D%0A%20%20B%5B%22%E7%BB%93%E7%AE%97%E6%B5%81%EF%BC%9Asettle%20%E6%97%B6%E5%88%BB%E4%B8%8E%E9%80%80%E6%AC%BE%E8%B4%9F%E8%A1%8C%22%5D%20--%3E%20R%0A%20%20R%20--%3E%20MM%5B%22%E5%95%86%E6%88%B7%E8%A7%A3%E6%9E%90%EF%BC%9A%E6%94%B6%E5%8D%95%E5%90%8D%E5%88%B0%E8%AF%81%E5%88%B8%EF%BC%8C%E5%B8%A6%E7%89%88%E6%9C%AC%22%5D%0A%20%20MM%20--%3E%20CAL%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%E6%A0%A1%E5%87%86%EF%BC%9A%E5%AF%B9%E7%85%A7%E5%8F%91%E5%8D%A1%E8%A1%8C%E4%B8%8E%E9%9B%B6%E5%94%AE%E5%BA%8F%E5%88%97%22%5D%0A%20%20CAL%20--%3E%20RES%5B%22%E8%A1%8C%E4%B8%9A%E4%B8%AD%E6%80%A7%E5%90%8E%E7%9A%84%E5%8F%91%E8%A1%8C%E4%BA%BA%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20R%20--%3E%20D%5B%22%E4%BA%A4%E4%BB%98%E5%BB%B6%E8%BF%9F%E5%88%86%E5%B8%83%22%5D%20--%3E%20RES%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"卡数据的边际价值为什么住在发行人残差：宏观消费意外早已被股债定价，主干课用刺激支票研究演示过这条地板；残差干净的前提是时钟与映射干净。授权时钟偏早所以更接近事件研究，结算时钟偏晚所以更接近现金流，两者的差本身是信息——预授权酒店与航空的分笔授权把这个差拉长到数周。不这么做的错法：把礼品卡销售当消费（销售时点与核销时点分离）；把发卡机构构成的漂移当成消费升级；把退款率的变化当成需求变化。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"授权到结算通常差一至三个工作日，退款回流可滞后数周；Baker 等（2020）识别刺激支票的消费响应时，消费按个体与类别细排，正是为了把到账日的机械性到账与真实支出分开。双时钟不是洁癖，是识别条件。")],-1)),E[6]||(E[6]=a("p",null,"两个时钟各自的失真路径——回答「混用一个日期到底错在哪」：",-1)),(B(),r(o,null,{default:e(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E7%AC%AC%200%20%E5%A4%A9%EF%BC%9A%E6%8E%88%E6%9D%83%EF%BC%88%E5%88%B7%E5%8D%A1%E7%9E%AC%E9%97%B4%EF%BC%89%22%5D%20--%3E%20B%5B%22%E7%AC%AC%201-3%20%E5%A4%A9%EF%BC%9A%E7%BB%93%E7%AE%97%EF%BC%88%E9%92%B1%E7%9C%9F%E6%AD%A3%E5%88%92%E8%B5%B0%EF%BC%89%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%92%A4%E9%94%80%20%2F%20%E6%94%B9%E9%A2%9D%EF%BC%9A%E6%8E%88%E6%9D%83%E6%B0%B8%E4%B8%8D%E7%BB%93%E7%AE%97%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8C%89%E6%8E%88%E6%9D%83%E6%97%A5%E8%AE%B0%E8%B4%A6%EF%BC%9A%E6%8A%8A%E6%B2%A1%E8%8A%B1%E7%9A%84%E7%AE%97%E6%88%90%E8%8A%B1%E4%BA%86%22%5D%0A%20%20B%20--%3E%20E%5B%22%E6%95%B0%E5%91%A8%E5%90%8E%EF%BC%9A%E9%80%80%E6%AC%BE%E8%B4%9F%E5%90%91%E5%9B%9E%E6%B5%81%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%8C%89%E7%BB%93%E7%AE%97%E6%97%A5%E8%AE%B0%E8%B4%A6%EF%BC%9A%E6%BC%8F%E7%9C%8B%E8%B4%AD%E4%B9%B0%E6%84%8F%E5%9B%BE%EF%BC%8C%E6%BB%9E%E5%90%8E%E6%95%B0%E5%91%A8%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E6%B6%88%E8%B4%B9%EF%BC%8C%E4%B8%A4%E7%A7%8D%E6%97%A5%E5%8E%86%E7%BB%99%E5%87%BA%E4%B8%A4%E5%B9%85%E5%9B%BE%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲家庭金融的因果问题——流动性约束与消费平滑是主干课与家庭金融文献的对象；用账户数据评估监管与产品设计（Agarwal, Chomsisengphet, Mahoney and Stroebel, 2015）是另一条应用线。卫星、文本、图谱各域不在此。个人级数据不可留存、不可交易使用，聚合门槛与删除义务的完整清单在<a href="/quant/web-data-compliance">网络数据合规</a>；卡数据的供应商条款常比通用条款更严，逐条入注册表。</p><p><span class="marginnote">常见误区：拿到明细数据先「存下来以后再分析」。对卡数据这是合规红线——个人级明细不可留存，只允许聚合层以上使用。正确顺序是先声明聚合口径与保留期限，再做任何分析；供应商条款往往比通用数据条款更严，逐条登记而不是凭印象。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双时钟是第一机制：授权与结算分开记账，退款是负行，聚合先声明用哪个时钟。</li><li>商户解析是一张带版本的图谱，映射修订走生效日，不回写历史。</li><li>代表性校准对照发卡行与官方序列；比率漂移时段只做方向不做水平。</li><li>边际价值在行业中性后的发行人残差，宏观层早被定价。</li><li>出处：Gross and Souleles, <em>QJE</em>, 2002；Ganong and Noel, <em>AER</em>, 2019；Baker, Farrokhnia, Meyer, Pagel and Yannelis, <em>RFS</em>, 2020；Agarwal, Chomsisengphet, Mahoney and Stroebel, <em>QJE</em>, 2015；Chetty, Friedman, Hendren, Stepner and Opportunity Insights。</li></ul>',5))])}const g=s(p,[["render",C]]);export{f as __pageData,g as default};
